/* -------------------------------------------------------------------------
 * NavIcon — small inline icon wrapper, atomic building block reused by
 * every sidebar/header entry so icon sizing stays consistent.
 * ---------------------------------------------------------------------- */
function NavIcon({
  children,
  size = 18,
  className = "",
}: {
  children: React.ReactNode;
  size?: number;
  className?: string;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={`shrink-0 ${className}`}
    >
      {children}
    </svg>
  );
}

